package com.bank.dispute;

public class DisputeView {

    public SlipNode reverseBetween(SlipNode head, int p, int q) {
        if (head == null || p == q) return head;
        SlipNode dummy = new SlipNode(-1);
        dummy.next = head;

        SlipNode beforeP = dummy;
        for (int i = 0; i < p - 1; i++) beforeP = beforeP.next;  // node before position p

        SlipNode segStart = beforeP.next;   // becomes the segment TAIL after reversal
        SlipNode previous = null, current = segStart;
        for (int i = 0; i < q - p + 1; i++) {   // reverse exactly q-p+1 nodes
            SlipNode next = current.next;
            current.next = previous;
            previous = current;
            current = next;
        }
        beforeP.next = previous;      // prefix → new segment head
        segStart.next = current;      // segment tail → suffix
        return dummy.next;
    }
}
