package com.bank.dispute;

import java.util.logging.Logger;

public class SublistDemo {
    private static final Logger log = Logger.getLogger(SublistDemo.class.getName());

    public static void main(String[] args) {
        SlipNode head = build(new int[]{1, 2, 3, 4, 5});
        log.info("Original: " + render(head));

        SlipNode out = new DisputeView().reverseBetween(head, 2, 4);
        log.info("Reversed positions 2..4: " + render(out));
    }

    static SlipNode build(int[] ids) {
        SlipNode d = new SlipNode(-1), t = d;
        for (int id : ids) { t.next = new SlipNode(id); t = t.next; }
        return d.next;
    }

    static String render(SlipNode n) {
        StringBuilder sb = new StringBuilder();
        while (n != null) { sb.append(n.id); if (n.next != null) sb.append(" -> "); n = n.next; }
        return sb.append(" -> null").toString();
    }
}
